/* strong guarantee: build off to the side, then commit by swapping ownership */
Err vec_assign(Vec *dst, const Vec *src) {
    int *buf = malloc(src->len * sizeof *buf);   /* fallible half: nothing changed yet */
    if (!buf) return ERR_ALLOC;                  /* dst is untouched                  */
    memcpy(buf, src->buf, src->len * sizeof *buf);
    free(dst->buf);                              /* commit: no allocation, cannot fail */
    dst->buf = buf;
    dst->len = src->len;
    return OK;
}
